code="\nfrom pathlib import Path\nimport dbus,hashlib,json,os,re,stat,subprocess\nos.umask(0o077);root=Path('/var/lib/samurai');out=root/'k220-final-health';out.mkdir(mode=0o700);base=root/'k220-baseline'\nassert Path('/proc/sys/kernel/random/boot_id').read_bytes()==(base/'boot-id-private.txt').read_bytes()\nassert Path('/sys/firmware/devicetree/base/model').read_bytes()==b'Realme X2 Pro (RMX1931CN)\\0' and os.uname().version.startswith('#183 ')\nstate=json.loads((root/'k220-r7-package-transaction/transaction-state-private.json').read_text());assert state['state']=='verified'\npolicy=json.loads((root/'k220-r7-package-transaction/policy-reload-state-private.json').read_text());assert policy['state']=='verified'\nmanifest=json.loads((root/'k220-r7-package-candidates/forward-manifest.json').read_text())\npaths={name for package in manifest['packages'] for name in package['files']}\noriginal=json.loads((root/'k214-baseline/products-before-private.json').read_text())\nfor name,digest in original.items():\n    if name.lstrip('/') not in paths and not name.endswith('/kernel/drivers/media/i2c/imx471.ko'):assert hashlib.sha256(Path(name).read_bytes()).hexdigest()==digest\nchecked=0\nfor package in manifest['packages']:\n    for name,item in package['files'].items():\n        p=Path('/')/name\n        if item['kind']=='symlink':assert p.is_symlink() and os.readlink(p)==item['target']\n        else:assert p.is_file() and hashlib.sha256(p.read_bytes()).hexdigest()==item['sha256'] and stat.S_IMODE(p.stat().st_mode)==item['mode']\n        checked+=1\ndevices={'sensor':Path('/sys/bus/i2c/devices/7-0010'),'camss':Path('/sys/bus/platform/devices/acb3000.camss'),'cci':Path('/sys/bus/platform/devices/ac4b000.cci')}\nassert (devices['sensor']/'driver').resolve().name=='imx471'\npm={name:(p/'power/runtime_status').read_text().strip() for name,p in devices.items()};assert all(value=='suspended' for value in pm.values())\nrails={}\nfor p in Path('/sys/class/regulator').glob('regulator.*'):\n    name=(p/'name').read_text().strip()\n    if name in ['cam-front-vdig','cam-front-vana']:rails[name]={n:(p/n).read_text().strip() for n in ['state','num_users','microvolts']}\nassert len(rails)==2 and all(x['state']=='disabled' and x['num_users']=='0' for x in rails.values())\nclocks=Path('/sys/kernel/debug/clk/clk_summary').read_text();mclk=next(l.split() for l in clocks.splitlines() if re.search(r'\\bcam_cc_mclk2_clk\\s',l));assert int(mclk[1])==0\npd=Path('/sys/kernel/debug/pm_genpd/pm_genpd_summary').read_text();assert re.search(r'genpd:3:acb3000.camss\\s+suspended\\s+0\\s',pd)\n(out/'clock-private.txt').write_text(clocks);(out/'genpd-private.txt').write_text(pd)\nfor name in ['imx471 7-0010','msm_csid0']:\n    nodes=[p for p in Path('/sys/class/video4linux').glob('v4l-subdev*') if (p/'name').read_text().strip()==name];assert len(nodes)==1\n    text=subprocess.check_output(['v4l2-ctl','-d','/dev/'+nodes[0].name,'--get-ctrl=test_pattern'],text=True,timeout=10);assert re.search(r'^test_pattern:\\s*0(?:\\s|\\(|$)',text)\nbus=dbus.SystemBus(private=True);props=dbus.Interface(bus.get_object('org.freedesktop.ModemManager1','/org/freedesktop/ModemManager1/Modem/0'),'org.freedesktop.DBus.Properties')\nloc=props.GetAll('org.freedesktop.ModemManager1.Modem.Location');assert int(loc['Enabled'])==0 and not loc['SignalsLocation'] and int(loc['GpsRefreshRate'])==30\nassert not bus.name_has_owner('org.freedesktop.GeoClue2')\nobjects=dbus.Interface(bus.get_object('org.bluez','/'),'org.freedesktop.DBus.ObjectManager').GetManagedObjects();adapters=[v['org.bluez.Adapter1'] for v in objects.values() if 'org.bluez.Adapter1' in v]\nassert len(adapters)==1 and not adapters[0]['Powered'] and not adapters[0]['Discovering'] and not any(v.get('org.bluez.Device1',{}).get('Connected',False) for v in objects.values());bus.close()\nwatch=json.loads((root/'gnss-assist/watch-state.json').read_text());(out/'watch-private.json').write_text(json.dumps(watch,indent=2)+'\\n');assert watch['running'] and not watch['active'] and watch['worker_starts']==watch['worker_completions']\nchrony=subprocess.run(['chronyc','tracking'],capture_output=True,text=True,timeout=10);(out/'chrony-private.txt').write_text(chrony.stdout+chrony.stderr)\nlog=subprocess.check_output(['dmesg']);(out/'dmesg-private.txt').write_bytes(log)\nfaults={k:log.count(v) for k,v in dict(warning=b'WARNING:',oops=b'Oops:',gpu=b'gpu fault:',slpi_fatal=b'fatal error received',bluetooth=b'Frame reassembly failed').items()};assert not any(faults.values())\nassert Path('/proc/sys/kernel/tainted').read_text().strip()=='0'\nrp={(p/'name').read_text().strip():(p/'state').read_text().strip() for p in Path('/sys/class/remoteproc').glob('remoteproc*')};assert len(rp)==3 and all(v=='running' for v in rp.values())\n\nwith (out/'nv-check-private.txt').open('wb') as log:\n    subprocess.run(['sha256sum','-c','/run/samurai-wifi/nv-source-hashes.txt'],check=True,stdout=log,stderr=subprocess.STDOUT,timeout=30)\nlegacy_checked=0;camera_owned=[];status=[]\nfor line in (root/'k212-before-reboot/userspace-check.sha256').read_text().splitlines():\n    digest,name=line.split(maxsplit=1);name=name.lstrip(' *');p=Path(name)\n    assert p.is_absolute() and len(digest)==64\n    if name.lstrip('/') in paths:\n        camera_owned.append(name);continue\n    assert hashlib.sha256(p.read_bytes()).hexdigest()==digest\n    legacy_checked+=1;status.append(name+': OK')\nassert '/etc/libcamera/configuration.yaml' in camera_owned\n(out/'noncamera-product-check-private.txt').write_text('\\n'.join(status)+'\\n')\nrecords={}\nfor block in Path('/lib/apk/db/installed').read_text().split('\\n\\n'):\n    fields={line[:1]:line[2:] for line in block.splitlines() if len(line)>1 and line[1]==':' and line[0] in 'PV'}\n    if 'P' in fields:records[fields['P']]=fields['V']\nassert len(records)==944 and all(records[p['name']]==p['version'] for p in manifest['packages'])\nwps=[]\nfor p in Path('/proc').iterdir():\n    if not p.name.isdigit():continue\n    try:\n        if (p/'comm').read_text().strip()=='wireplumber' and int((p/'status').read_text().split('Uid:',1)[1].split()[0])==10000:wps.append(p)\n    except OSError:pass\nassert len(wps)==1;wp=wps[0];assert 'libcamera.so' in (wp/'maps').read_text()\nfor line in (wp/'maps').read_text().splitlines():\n    if '/usr/lib/libcamera' in line:\n        path=Path(line.split()[-1]);assert path.is_file()\n        expected=[item['sha256'] for package in manifest['packages'] for name,item in package['files'].items() if name==str(path).lstrip('/') and item['kind']=='file'];assert len(expected)==1 and hashlib.sha256(path.read_bytes()).hexdigest()==expected[0]\nimport struct\nmodule=Path('/usr/lib/modules')/os.uname().release/'kernel/drivers/media/i2c/imx471.ko'\ndata=module.read_bytes();assert hashlib.sha256(data).hexdigest()=='e49dab26b05a325df8da64bb5c4b57c29cd51d1dcf15f5d4ed4dcb53033e66f1'\noffset=struct.unpack_from('<Q',data,40)[0];size,count,strings=struct.unpack_from('<HHH',data,58)\nheaders=[struct.unpack_from('<IIQQQQIIQQ',data,offset+i*size) for i in range(count)];header=headers[strings];names=data[header[4]:header[4]+header[5]]\nnotes=[data[h[4]:h[4]+h[5]] for h in headers if names[h[0]:].split(b'\\0',1)[0]==b'.note.gnu.build-id'];assert len(notes)==1 and notes[0]==Path('/sys/module/imx471/notes/.note.gnu.build-id').read_bytes()\nassert Path('/sys/module/imx471/parameters/unprocessed_fullres').read_text().strip()=='N'\nassert Path('/sys/bus/i2c/devices/7-0010/of_node/port/endpoint/link-frequencies').read_bytes()==struct.pack('>QQQ',200000000,400000000,748800000)\nbefore={}\nfor block in (root/'k220-r7-package-transaction/installed-before-private.txt').read_text().split('\\n\\n'):\n    ns=[l[2:] for l in block.splitlines() if l.startswith('P:')]\n    if ns:before[ns[0]]=block\nafter={}\nfor block in Path('/lib/apk/db/installed').read_text().split('\\n\\n'):\n    ns=[l[2:] for l in block.splitlines() if l.startswith('P:')]\n    if ns:after[ns[0]]=block\nselected={p['name'] for p in manifest['packages']};assert set(after)==set(before) and all(after[name]==block for name,block in before.items() if name not in selected)\n\nassert '(deleted)' not in '\\n'.join(line for line in (wp/'maps').read_text().splitlines() if '/usr/lib/libcamera' in line)\nreport=dict(stage=220,legacy_non_camera_product_entries_verified=legacy_checked,camera_owned_legacy_entries_verified_against_current_signed_package=len(camera_owned),same_current219_boot=True,kernel183_and_boot219_deployment_retained=True,timing_module_file_and_loaded_note_verified=True,experimental_full_mode_disabled=True,unrelated_937_package_records_unchanged=True,camera_packages_upgraded_and_native_transaction_verified=True,installed_package_count=944,camera_payload_records_verified=checked,static_front_still_bound=True,camera_devices_pm=pm,front_rails_disabled_zero_users=True,mclk_off_and_own_mmcx_vote_zero=True,all_test_patterns_disabled=True,new_wireplumber_camera_libraries_loaded=True,gps_enabled=0,signals_location=False,gps_refresh_rate=30,bt_powered=False,bt_connections=0,gnss_watcher_idle=True,gnss_time_prepared=watch['time_prepared'],gnss_time_preparation_attempts=watch['time_preparation_starts'],chrony_normal=chrony.returncode==0 and 'Normal' in chrony.stdout,remoteprocs=rp,taint=0,fault_counts=faults,nv_and_non_camera_product_programs_preserved=True,no_flash_or_reboot=True,uptime_seconds=float(Path('/proc/uptime').read_text().split()[0]))\n(out/'summary.json').write_text(json.dumps(report,indent=2)+'\\n');print(json.dumps(report))\n"
